import{z as t,x as s,o as a,c as l,q as B,j as r,D as e,d as o,s as A,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"异质信念与交易","description":"","frontmatter":{"title":"异质信念与交易","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/apt-heterogeneous-beliefs.md","filePath":"econ/apt-heterogeneous-beliefs.md","lastUpdated":1791413859000}'),p={name:"econ/apt-heterogeneous-beliefs.md"};function d(c,E,h,D,m,C){const n=s("Mermaid");return a(),l("div",null,[E[2]||(E[2]=B('<h1 id="异质信念与交易" tabindex="-1">异质信念与交易 <a class="header-anchor" href="#异质信念与交易" aria-label="Permalink to &quot;异质信念与交易&quot;">​</a></h1><div class="epigraph"><p>当卖空比买入贵，价格就不再征询平均意见，只听最乐观的那一个；分歧本身不是噪声，它是一项被交易的资产。</p><footer>—— 据 Miller, *Journal of Finance* 1977；Harrison and Kreps 1978；Scheinkman and Xiong, *JPE* 2003 整理</footer></div><p><a href="/econ/apt-sdf-deep">上一课</a>把全部定价压进一个核 \\(m\\)，但那个核默认市场上所有投资者读同一份信号、得出同一份后验。缺口从这份默认的裂缝开始：信念一旦分散，谁的价格算数？换手从哪里来？价格与基本面还差多少？完备市场加共同先验时交易根本无从发生（Milgrom–Stokey 1982 的无交易定理）；实际市场庞大的换手率说明必有东西被打破——先验不同、信号解读不同，或对信号精度过度自信。本课写这三条裂缝如何各自变成风险溢价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同质信念的代表性主体把「定价者是谁」藏起来了。信念分散后问题显形：悲观者若能卖空，价格落在双方估值的加权上；卖空受限时，悲观者只能离场，价格由乐观者独写——<a href="/econ/harrison-kreps-speculation">Miller 1977 的命题</a>从这里起步。更深一层：若持有者随时可能遇到更乐观的新买家，资产今天的价格就含一项「把它再卖出去」的期权价值，可以高于在场每一个人的持有价值。缺口是把三件事连起来：分歧的来源、约束的方向、由此生成的溢价与换手。</p><p><span class="marginnote">Harrison–Kreps 1978 的要点一句话可记：连续变化的信念加卖空约束下，价格严格高于所有投资者的最高持有价值——溢价全部来自再售期权；Scheinkman–Xiong 2003 把同一条机制推到换手上，模型同时给出泡沫与高换手这对孪生预言。</span></p><p><span class="marginnote">「卖空」是先借入股票卖出、日后再买回来归还的交易方式，让看跌的人也能把钱押上自己的判断；「卖空约束」指借券太贵或干脆被禁止。一旦看跌者无法出场，市场里就只剩看涨者的报价——价格征询的不再是全体意见，而是被约束筛过的乐观意见。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三步。第一，分歧进入价格的水平：卖空约束下边际买者是乐观者，意见分歧越大、卖空越贵，价格越高，随后的收益越低——这是横截面可检验的「分歧溢价」。第二，再售期权：Harrison–Kreps 1978 把它算成显式项，价格等于持有价值加再售期权；<a href="/econ/harrison-kreps-speculation">Harrison–Kreps 异质信念</a>那课已经立过此账，本课强调它对「泡沫不需要傻瓜」的含义：每个人都理性地付溢价，因为期权在别人手里。第三，分歧的内生来源：对信号精度的过度自信（<a href="/econ/dhs-overconfidence">DHS 的机制</a>）使分歧随新信息不断刷新，<a href="/econ/scheinkman-xiong">Scheinkman–Xiong 换手与泡沫</a>由此同时定价换手与价格；信息缓慢扩散时分歧先放大后收敛，给出动量转崩盘的形状（<a href="/econ/hong-stein-diffusion">Hong–Stein 信息扩散</a>）。</p>',9)),(a(),r(i,null,{default:e(()=>[A(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E5%88%86%E6%AD%A7%E6%9D%A5%E6%BA%90%3A%20%E8%A7%A3%E8%AF%BB%E5%B7%AE%E5%BC%82%20%2F%20%E8%BF%87%E5%BA%A6%E8%87%AA%E4%BF%A1%22%5D%20--%3E%20CON%5B%22%E5%8D%96%E7%A9%BA%E7%BA%A6%E6%9D%9F%3A%20%E6%82%B2%E8%A7%82%E8%80%85%E7%A6%BB%E5%9C%BA%22%5D%0A%20%20CON%20--%3E%20MARG%5B%22%E8%BE%B9%E9%99%85%E4%B9%B0%E8%80%85%20%3D%20%E4%B9%90%E8%A7%82%E8%80%85%22%5D%0A%20%20MARG%20--%3E%20PRC%5B%22%E4%BB%B7%E6%A0%BC%20%3D%20%E6%8C%81%E6%9C%89%E4%BB%B7%E5%80%BC%20%2B%20%E5%86%8D%E5%94%AE%E6%9C%9F%E6%9D%83%22%5D%0A%20%20PRC%20--%3E%20TO%5B%22%E9%AB%98%E6%8D%A2%E6%89%8B%3A%20%E5%88%86%E6%AD%A7%E5%88%B7%E6%96%B0%E5%8D%B3%E4%BA%A4%E6%98%93%22%5D%0A%20%20PRC%20--%3E%20RET%5B%22%E9%9A%8F%E5%90%8E%E7%9A%84%E4%BD%8E%E6%94%B6%E7%9B%8A%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>全部机制系于边际定价者的更换：价格不再是均值，而是信念分布的乐观分位数。于是交易量不需要新信息——解读分歧的刷新本身就是交易的理由，这解释了换手率与随后收益负相关的实证组合。再看它对核语法的意义：上一课的 \\(m\\) 由「边际效用」构造，本课的 \\(m\\) 由「边际买者」构造，两者在卖空不受限时重合，受限时分道。为什么不套利掉这部分溢价？借券贵、期限错，且偏离可以先更深——<a href="/econ/limits-to-arbitrage">套利限制</a>与<a href="/econ/noise-trader-risk">噪声交易者风险</a>给出均衡里的存活条件。调查测得的分歧度与换手正相关、与随后收益负相关（<a href="/econ/survey-expectations">调查预期</a>），是这条链最直接的证据。</p><p>上一张图画因果链；这一张只换一个变量——卖空是否自由——看同一份信念分布下价格落在哪里，对比出「边际买者更换」的全部含义。</p>',3)),(a(),r(i,null,{default:e(()=>[A(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIST%5B%22%E6%8A%95%E8%B5%84%E8%80%85%E7%9A%84%E4%BC%B0%E5%80%BC%E5%88%86%E5%B8%83%EF%BC%9A%E4%BB%8E%E6%82%B2%E8%A7%82%E5%88%B0%E4%B9%90%E8%A7%82%E6%8E%92%E5%BC%80%22%5D%20--%3E%20FREE%5B%22%E5%8D%96%E7%A9%BA%E8%87%AA%E7%94%B1%EF%BC%9A%E6%82%B2%E8%A7%82%E8%80%85%E4%B9%9F%E8%83%BD%E5%85%A5%E5%9C%BA%22%5D%0A%20%20DIST%20--%3E%20CON%5B%22%E5%8D%96%E7%A9%BA%E5%8F%97%E9%99%90%EF%BC%9A%E6%82%B2%E8%A7%82%E8%80%85%E5%8F%AA%E8%83%BD%E7%A6%BB%E5%9C%BA%22%5D%0A%20%20FREE%20--%3E%20P1%5B%22%E4%BB%B7%E6%A0%BC%20%E2%89%88%20%E5%90%84%E6%96%B9%E4%BC%B0%E5%80%BC%E7%9A%84%E5%8A%A0%E6%9D%83%E5%B9%B3%E5%9D%87%22%5D%0A%20%20CON%20--%3E%20P2%5B%22%E4%BB%B7%E6%A0%BC%E7%94%B1%E4%B9%90%E8%A7%82%E7%AB%AF%E7%9A%84%E5%88%86%E4%BD%8D%E6%95%B0%E5%86%99%E5%87%BA%22%5D%0A%20%20P2%20--%3E%20OPT%5B%22%E8%8B%A5%E8%BF%98%E5%8F%AF%E8%83%BD%E5%87%BA%E7%8E%B0%E6%9B%B4%E4%B9%90%E8%A7%82%E7%9A%84%E4%B9%B0%E5%AE%B6%EF%BC%9A%E5%86%8D%E5%8F%A0%E4%B8%80%E5%B1%82%E5%86%8D%E5%94%AE%E6%9C%9F%E6%9D%83%22%5D%0A%20%20P1%20--%3E%20CMP%5B%22%E5%90%8C%E4%B8%80%E8%B5%84%E4%BA%A7%EF%BC%8C%E4%B8%A4%E7%A7%8D%E6%83%85%E5%BD%A2%E7%9A%84%E4%BB%B7%E6%A0%BC%E5%B7%AE%E5%B0%B1%E6%98%AF%E5%88%86%E6%AD%A7%E6%BA%A2%E4%BB%B7%E7%9A%84%E9%87%8F%E7%BA%A7%22%5D%0A%20%20P2%20--%3E%20CMP%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">数字实例：十位投资者对一只股票的估值从 50 元到 90 元排开，均值约 70 元。卖空自由时价格接近 70 元；卖空受限后，价格由最乐观的几位写，比如 85 元。日后分歧一旦收敛，价格向 70 元回落，高位接手者吃到的负收益就是「分歧溢价」的兑现。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>分歧不必然高估：约束若对买卖双向都贵——借券贵、加杠杆同样贵——低估也会出现，方向由哪一侧受限更紧决定。共同先验加完备市场下投机溢价严格为零（Varian 1985；Milgrom–Stokey 1982），所以「异质信念定价」必须与市场不完备或非共同先验配套读，单独引用是把前提丢了一半。度量侧：卖空成本、换手、调查宽度各有噪声，横截面证据集中在小市值与高约束子集，外推到大盘蓝筹要克制。</p><p><span class="marginnote">常见误区：以为「异质信念必然推高价格」。方向其实取决于哪一侧被约束卡得更紧——借券贵时偏乐观高估，加杠杆贵时同样可以出现低估；而在完备市场加共同先验的基准下，投机溢价干脆严格为零。「分歧看涨」是有前提的结论，不是定理。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>卖空约束把边际定价者换成乐观者；分歧越大，价格偏离越高，随后收益越低。</li><li>再售期权让价格可高于所有人的持有价值——泡沫不需要非理性者，只需要约束与分歧。</li><li>换手是分歧的观测器：交易量不需要新信息，只需要解读不同。</li><li>前提是市场不完备或非共同先验；完备加共同先验时本课的溢价为零。</li><li>出处：Miller, <em>Journal of Finance</em> 1977；Harrison and Kreps 1978；Scheinkman and Xiong, <em>JPE</em> 2003；Hong and Stein, <em>JEP</em> 2007。</li></ul>',6))])}const u=t(p,[["render",d]]);export{_ as __pageData,u as default};
